#!/bin/bash\n\necho \"🎬 Studio AI - Local Quick Start\"\necho \"===============================\"\necho \"\"\n\n# Check Node.js\nif ! command -v node &> /dev/null; then\n    echo \"❌ Node.js not found. Please install Node.js 18+\"\n    echo \"   Visit: https://nodejs.org/\"\n    exit 1\nfi\n\necho \"✅ Node.js found: $(node --version)\"\necho \"\"\n\n# Install backend dependencies\necho \"📦 Installing backend dependencies...\"\nnpm install\n\nif [ $? -ne 0 ]; then\n    echo \"❌ Failed to install backend dependencies\"\n    exit 1\nfi\n\necho \"✅ Backend dependencies installed\"\necho \"\"\n\n# Create client if not exists\nif [ ! -d \"client\" ]; then\n    echo \"📱 Creating React frontend...\"\n    npx create-react-app client\nfi\n\n# Install frontend dependencies\necho \"📦 Installing frontend dependencies...\"\ncd client\nnpm install\n\nif [ $? -ne 0 ]; then\n    echo \"❌ Failed to install frontend dependencies\"\n    exit 1\nfi\n\ncd ..\necho \"✅ Frontend dependencies installed\"\necho \"\"\n\n# Setup environment\nif [ ! -f .env ]; then\n    echo \"⚙️ Creating .env file...\"\n    cp .env.example .env\n    echo \"✅ Created .env file\"\n    echo \"⚠️  Please edit .env with your GPU settings\"\nelse\n    echo \"✅ .env file exists\"\nfi\n\necho \"\"\n\n# Create directories\necho \"📁 Creating directories...\"\nmkdir -p uploads outputs models logs\necho \"✅ Directories created\"\necho \"\"\n\necho \"================================================================\"\necho \"✅ Setup Complete!\"\necho \"================================================================\"\necho \"\"\necho \"🚀 To start the app, run:\"\necho \"   npm run dev\"\necho \"\"\necho \"🌐 Then open:\"\necho \"   Frontend: http://localhost:3000\"\necho \"   Backend:  http://localhost:5000\"\necho \"\"\necho \"📖 Check out the docs/ folder for more info\"\necho \"\"\necho \"🎉 Ready to create amazing videos!\"\necho \"================================================================\"\n"
